# Writes the hedra command files of planet-hop's world: six little planets (meadow, dune, ice,
# mushroom, lava, giant), the collectable star, the flame, the exhaust puff, sparks, debris, the
# star field and the nebula. Run from models/env: /usr/bin/python3 make_env.py.
# hedra: up Z, front -Y (the camera side). The game plays in hedra's X-Z plane (glTF X-Y): props
# stand on the planets' rims there, so they show on the silhouette as the planets turn.
# Colours are exact hept32 hex (sRGB 0..1). Each planet is baked at its largest radius (1.5 m).
import math, random

def rgb(h):
    h = h.lstrip("#")
    return " ".join(f"{int(h[i:i + 2], 16) / 255:.4f}" for i in (0, 2, 4))

def mat(name, hexc, emit=False):
    s = f"material new {name} --base-color {rgb(hexc)} --no-slot"
    return s + (f" --emission {rgb(hexc)}" if emit else "")

def orient(n):
    """rotation (x y z degrees, extrinsic XYZ) taking +Z to the unit vector n"""
    th = math.degrees(math.acos(max(-1, min(1, n[2]))))
    ph = math.degrees(math.atan2(n[1], n[0]))
    return f"0 {th:.2f} {ph:.2f}"

def rim(a_deg, e_deg=0.0):
    """unit direction at angle a in the play plane (X-Z), tipped e towards the camera (-Y)"""
    a, e = math.radians(a_deg), math.radians(e_deg)
    return (math.cos(a) * math.cos(e), -math.sin(e), math.sin(a) * math.cos(e))

R = 1.5

def body(name, hexmat, seed, half=True):
    L = [f"add mesh ico-sphere --name {name} --subdivisions 2 --radius {R}", f"material assign {hexmat}",
         f"active {name}", "mode edit"]
    if half:
        # the back is never seen (the planets turn about the view axis): only the front half and rim
        L += ['select face where "normal.y > 0.3"', "delete only-faces"]
    L += ["select all", f"randomize --amount 0.05 --seed {seed}", "mode object"]
    return L

def place_on(name, n, sink=0.06):
    p = [c * (R - sink) for c in n]
    return f"--location {p[0]:.3f} {p[1]:.3f} {p[2]:.3f} --rotation {orient(n)}"

def tree(i, n, h=0.62, r=0.30):
    # a pine: a trunk and one fat 6-sided cone, standing along n
    L = []
    t = [c * (R + 0.08) for c in n]
    L += [f"add mesh cube --name Trunk{i} --size 1 --location 0 0 0", "scale 0.17 0.17 0.32", "apply --scale",
          f"set rotation {orient(n)}", f"set location {t[0]:.3f} {t[1]:.3f} {t[2]:.3f}", "material assign Trunk"]
    c = [cc * (R + 0.2 + h / 2) for cc in n]
    L += [f"add mesh cone --name Pine{i} --vertices 6 --radius1 {r} --radius2 0 --depth {h} "
          f"--location {c[0]:.3f} {c[1]:.3f} {c[2]:.3f} --rotation {orient(n)}", "material assign Leaf"]
    return L

def write(name, lines, header):
    open(f"{name}.txt", "w").write("\n".join([f"# {header} Generated by make_env.py.", "new"] + lines) + "\n")

# ---- meadow: a green planet with pines, a little house with a red roof, two rocks
L = [mat("Grass", "#08b23b"), mat("Leaf", "#005f41"), mat("Trunk", "#8a4926"), mat("Wall", "#c5cddb"),
     mat("Roof", "#da2424"), mat("Rock", "#686b72")]
L += body("Meadow", "Grass", 3)
for i, (a, e, h) in enumerate([(20, 0, 0.62), (62, 10, 0.5), (150, 0, 0.7), (205, 25, 0.55), (300, 0, 0.6), (330, 30, 0.5)]):
    L += tree(i, rim(a, e), h)
n = rim(105, 5)
w = [c * (R + 0.18) for c in n]
L += [f"add mesh cube --name House --size 1 --location 0 0 0", "scale 0.5 0.42 0.42", "apply --scale",
      f"set rotation {orient(n)}", f"set location {w[0]:.3f} {w[1]:.3f} {w[2]:.3f}", "material assign Wall"]
rf = [c * (R + 0.5) for c in n]
L += [f"add mesh cone --name RoofC --vertices 4 --radius1 0.42 --radius2 0 --depth 0.32 --location 0 0 0 --rotation 0 0 45",
      "apply --rotation", f"set rotation {orient(n)}", f"set location {rf[0]:.3f} {rf[1]:.3f} {rf[2]:.3f}", "material assign Roof"]
for i, a in enumerate([250, 175]):
    q = [c * (R + 0.05) for c in rim(a, 15)]
    L += [f"add mesh ico-sphere --name Rock{i} --subdivisions 1 --radius 0.2 --location {q[0]:.3f} {q[1]:.3f} {q[2]:.3f}", "material assign Rock"]
L += ["select all", "shade flat", "export meadow.glb"]
write("meadow", L, "Meadow planet: r 1.5 grass ball, six pines, a red-roofed house, two rocks.")

# ---- dune: a sand planet with crater rims, cacti and a pyramid
L = [mat("Sand", "#de9751"), mat("Crater", "#b66831"), mat("Cactus", "#08b23b"), mat("Pyramid", "#fbbe82")]
L += body("Dune", "Sand", 5)
rnd = random.Random(11)
for i, (a, e) in enumerate([(40, 50), (200, 45), (300, 60), (120, 65)]):
    n = rim(a, e)
    p = [c * (R - 0.02) for c in n]
    rr = rnd.uniform(0.25, 0.4)
    L += [f"add mesh torus --name Crater{i} --major-segments 8 --minor-segments 4 --major-radius {rr:.2f} --minor-radius 0.09 "
          f"--location {p[0]:.3f} {p[1]:.3f} {p[2]:.3f} --rotation {orient(n)}", "scale 1 1 0.6", "material assign Crater"]
for i, a in enumerate([10, 140, 250]):
    n = rim(a)
    c = [cc * (R + 0.25) for cc in n]
    L += [f"add mesh cylinder --name Cactus{i} --vertices 6 --radius 0.12 --depth 0.62 --location {c[0]:.3f} {c[1]:.3f} {c[2]:.3f} --rotation {orient(n)}",
          "material assign Cactus"]
    # one arm, sideways in the play plane then up
    t = (-n[2], 0, n[0])
    arm = [c[k] + t[k] * 0.17 + n[k] * 0.05 for k in range(3)]
    L += [f"add mesh cylinder --name Arm{i} --vertices 6 --radius 0.09 --depth 0.3 --location {arm[0]:.3f} {arm[1]:.3f} {arm[2]:.3f} --rotation {orient(n)}",
          "material assign Cactus"]
n = rim(75, 5)
c = [cc * (R + 0.12) for cc in n]
L += [f"add mesh cone --name Pyramid --vertices 4 --radius1 0.5 --radius2 0 --depth 0.55 --location 0 0 0 --rotation 0 0 45",
      "apply --rotation", f"set rotation {orient(n)}", f"set location {c[0]:.3f} {c[1]:.3f} {c[2]:.3f}", "material assign Pyramid"]
L += ["select all", "shade flat", "export dune.glb"]
write("dune", L, "Dune planet: r 1.5 sand ball, crater rims, three cacti, a pyramid.")

# ---- ice: a white planet bristling with cyan crystals
L = [mat("Snow", "#ffffff"), mat("Crystal", "#5ee9e9"), mat("Deep", "#2890dc")]
L += body("Ice", "Snow", 7)
for i, (a, e, h, m) in enumerate([(0, 0, 0.8, "Crystal"), (30, 20, 0.5, "Deep"), (95, 0, 0.65, "Crystal"), (128, 30, 0.45, "Crystal"),
                                    (185, 0, 0.75, "Crystal"), (232, 15, 0.5, "Deep"), (280, 0, 0.6, "Crystal"), (320, 35, 0.45, "Crystal")]):
    n = rim(a, e)
    c = [cc * (R + h / 2 - 0.05) for cc in n]
    L += [f"add mesh cone --name Crystal{i} --vertices 4 --radius1 0.2 --radius2 0 --depth {h} --location {c[0]:.3f} {c[1]:.3f} {c[2]:.3f} --rotation {orient(n)}",
          f"material assign {m}"]
L += ["select all", "shade flat", "export ice.glb"]
write("ice", L, "Ice planet: r 1.5 snow ball with cyan crystal spikes.")

# ---- mushroom: a pink candy planet with paler patches and red-capped mushrooms
L = [mat("Candy", "#f94e6d"), mat("Patch", "#f78d8d"), mat("Stem", "#ffffff"), mat("Cap", "#da2424")]
L += body("Shroom", "Candy", 9)
L += ["active Shroom", "mode edit", "select mode face", "select none", "select random --ratio 0.22 --seed 4", "material assign Patch", "mode object"]
for i, (a, e, s) in enumerate([(15, 0, 1.0), (80, 20, 0.8), (160, 0, 1.15), (230, 25, 0.8), (290, 0, 0.95)]):
    n = rim(a, e)
    st = [cc * (R + 0.15 * s) for cc in n]
    cp = [cc * (R + 0.36 * s) for cc in n]
    L += [f"add mesh cylinder --name Stem{i} --vertices 6 --radius {0.11 * s:.3f} --depth {0.4 * s:.3f} --location {st[0]:.3f} {st[1]:.3f} {st[2]:.3f} --rotation {orient(n)}",
          "material assign Stem",
          f"add mesh ico-sphere --name Cap{i} --subdivisions 1 --radius {0.3 * s:.3f} --location 0 0 0", "scale 1 1 0.55", "apply --scale",
          f"set rotation {orient(n)}", f"set location {cp[0]:.3f} {cp[1]:.3f} {cp[2]:.3f}", "material assign Cap"]
L += ["select all", "shade flat", "export mushroom.glb"]
write("mushroom", L, "Mushroom planet: r 1.5 pink candy ball with pale patches, five red-capped mushrooms.")

# ---- lava: a dark rock planet with glowing cracks (unlit faces) and three volcanoes
L = [mat("Basalt", "#353658"), mat("Lava", "#ef6e10", True), mat("Cone", "#686b72"), mat("Crater", "#ecab11", True)]
L += body("Lava", "Basalt", 13)
L += ["active Lava", "mode edit", "select mode face", "select none", "select random --ratio 0.16 --seed 8", "material assign Lava", "mode object"]
for i, (a, e, s) in enumerate([(35, 0, 1.0), (150, 10, 0.8), (265, 0, 1.1)]):
    n = rim(a, e)
    c = [cc * (R + 0.18 * s) for cc in n]
    t = [cc * (R + 0.4 * s) for cc in n]
    L += [f"add mesh cone --name Volcano{i} --vertices 7 --radius1 {0.45 * s:.3f} --radius2 {0.16 * s:.3f} --depth {0.45 * s:.3f} --location {c[0]:.3f} {c[1]:.3f} {c[2]:.3f} --rotation {orient(n)}",
          "material assign Cone",
          f"add mesh cylinder --name Vent{i} --vertices 7 --radius {0.15 * s:.3f} --depth 0.08 --location {t[0]:.3f} {t[1]:.3f} {t[2]:.3f} --rotation {orient(n)}",
          "material assign Crater"]
L += ["select all", "shade flat", "export lava.glb"]
write("lava", L, "Lava planet: r 1.5 basalt ball with glowing cracks, three volcanoes with hot vents.")

# ---- giant: a banded gas giant (whole ball: its ring passes behind it) with a tilted cyan ring
L = [mat("Cream", "#fbbe82"), mat("Band", "#ef6e10"), mat("Ring", "#5ee9e9")]
L += body("Giant", "Cream", 17, half=False)
L += ["active Giant", "mode edit", "select mode face", "select none",
      'select face where "abs(pos.z - 0.55) < 0.22 || abs(pos.z + 0.35) < 0.18"', "material assign Band", "mode object"]
L += ["add mesh torus --name Ring --major-segments 20 --minor-segments 4 --major-radius 2.25 --minor-radius 0.16",
      "scale 1 1 0.3", "apply --scale", "set rotation 16 0 0", "apply --rotation", "set rotation 0 -20 0", "apply --rotation",
      "material assign Ring"]
L += ["select all", "shade flat", "export giant.glb"]
write("giant", L, "Gas giant: r 1.5 banded ball and a tilted cyan ring 4.5 m across.")

# ---- the collectable star: a fat five-pointed star in the play plane, unlit gold
L = [mat("Gold", "#ece910", True)]
L += ["add mesh cylinder --name Core --vertices 10 --radius 0.17 --depth 0.18 --location 0 0 0 --rotation 90 0 0"]
names = ["Core"]
for k in range(5):
    a = 90 + k * 72
    n = (math.cos(math.radians(a)), 0, math.sin(math.radians(a)))
    c = [cc * 0.3 for cc in n]
    L += [f"add mesh cone --name Spike{k} --vertices 4 --radius1 0.15 --radius2 0 --depth 0.34 --location {c[0]:.3f} {c[1]:.3f} {c[2]:.3f} --rotation {orient(n)}"]
    names.append(f"Spike{k}")
L += ["select " + " ".join(names), "active Core", "join", "material assign Gold", "shade flat", "export star.glb"]
write("star", L, "Collectable star: five spikes round a core, 0.95 m across, unlit gold.")

# ---- flame: a cone pointing down from the nozzle (origin at its top: the nozzle's mouth)
write("flame", [mat("Sheath", "#ecab11", True), mat("Core", "#ffffff", True),
      "add mesh cone --name Sheath --vertices 6 --radius1 0.06 --radius2 0.22 --depth 0.7 --location 0 0 -0.35",
      "material assign Sheath",
      "add mesh cone --name Core --vertices 6 --radius1 0.05 --radius2 0.13 --depth 0.42 --location 0 -0.1 -0.22",
      "material assign Core", "select all", "shade flat", "export flame.glb"],
      "Thruster flame: a 6-sided cone 0.7 m long pointing down, a white core in a gold sheath, origin at its top.")

# ---- exhaust puff, spark, debris chunk
write("puff", [mat("Puff", "#c5cddb"), "add mesh ico-sphere --name Puff --subdivisions 1 --radius 0.2",
      "material assign Puff", "shade flat", "export puff.glb"], "Exhaust puff: a faceted ball 0.4 m across.")
write("spark", [mat("Spark", "#ece910", True), "add mesh cube --name Spark --size 0.16",
      "material assign Spark", "export spark.glb"], "Spark: a 0.16 m unlit cube.")
write("chunk", [mat("Hull", "#ffffff"), mat("Trim", "#da2424"),
      "add mesh ico-sphere --name Chunk --subdivisions 1 --radius 0.17", "scale 1.3 0.8 0.9", "apply --scale", "material assign Trim",
      "active Chunk", "mode edit", "select mode face", "select none", 'select face where "pos.z > 0.02"', "material assign Hull", "mode object",
      "shade flat", "export chunk.glb"], "Debris chunk: a squashed ico ball, half red half white.")

# ---- star field tile: specks on a plane 12 m back (glTF z -12), 20 m wide: the game leapfrogs two
# copies with parallax. One to two art pixels each, white, gold or cyan.
rnd = random.Random(21)
L = [mat("StarW", "#ffffff", True), mat("StarY", "#ece910", True)]
groups = {"StarW": [], "StarY": []}
for i in range(70):
    x, z = rnd.uniform(-10, 10), rnd.uniform(-6.5, 6.5)
    size = 0.16 if rnd.random() < 0.18 else 0.1
    g = rnd.choice(["StarW", "StarW", "StarY"])
    groups[g].append(f"S{i}")
    L.append(f"add mesh cube --name S{i} --size {size} --location {x:.3f} 0 {z:.3f}")
    if size > 0.12 and rnd.random() < 0.6:
        # a twinkle: a plus of three cubes
        groups[g] += [f"S{i}a", f"S{i}b"]
        L += [f"add mesh cube --name S{i}a --size 0.1 --location {x - 0.12:.3f} 0 {z:.3f}",
              f"add mesh cube --name S{i}b --size 0.1 --location {x + 0.12:.3f} 0 {z:.3f}"]
for g, ns in groups.items():
    L += ["select " + " ".join(ns), f"active {ns[0]}", "join", f"material assign {g}"]
L += ["select all", "export stars.glb"]
write("stars", L, "Star field tile: 70 unlit specks, 20 x 13 m, white and gold.")

# ---- nebula tile: soft-looking flat clouds (unlit lighter blue) and two far little planets
rnd = random.Random(5)
L = [mat("Cloud", "#2890dc", True), mat("Far1", "#c12458"), mat("Far2", "#b66831")]
cl = []
for i in range(6):
    # a cloud: a row of round, flat puffs, the middle ones biggest (a bumpy top, a flatter bottom)
    cx, cz = -8.5 + i * 3.4 + rnd.uniform(-0.6, 0.6), rnd.uniform(-4.5, 4.5)
    n = rnd.randint(4, 6)
    for j in range(n):
        u = (j - (n - 1) / 2) / max(1, (n - 1) / 2)
        r = (0.75 - 0.35 * abs(u)) * rnd.uniform(0.85, 1.15)
        nm = f"C{i}_{j}"
        cl.append(nm)
        L += [f"add mesh ico-sphere --name {nm} --subdivisions 2 --radius {r:.2f} "
              f"--location {cx + u * 1.3:.2f} 0 {cz + r * 0.45:.2f}", "scale 1.15 0.15 0.85", "apply --scale"]
L += ["select " + " ".join(cl), f"active {cl[0]}", "join", "material assign Cloud",
      "add mesh ico-sphere --name FarA --subdivisions 2 --radius 0.45 --location -6.5 -0.5 3.6", "material assign Far1",
      "add mesh ico-sphere --name FarB --subdivisions 2 --radius 0.3 --location 5.5 -0.5 -3.9", "material assign Far2",
      "select all", "shade flat", "export nebula.glb"]
write("nebula", L, "Nebula tile: six flat unlit blue clouds of round puffs and two far little planets, 20 x 10 m.")
